contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        uint before = c.tokenBalance(address(this));
        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }
        uint afterBal = c.tokenBalance(address(this));
        if (before == 0) {
            assert(!reverted && afterBal == 20);
        } else {
            assert(reverted && afterBal == before);
        }
    }
    fallback(bytes calldata) external returns (bytes memory) {
        // emulate Bank.supportsToken(): return keccak256("Nu Token")
        if (msg.sig == keccak256("supportsToken()")) {
            bytes32 h = keccak256(abi.encodePacked("Nu Token"));
            return abi.encode(h);
        }
        return "";
    }
    receive() external payable {}
}

